INSERT INTO `risetfakultas` (`id`, `nama`, `fakultas_id`, `created_at`, `updated_at`) VALUES
(1, 'Sustainability Innovation for Planning, Development and Infrastructure', 1, NULL, NULL),
(2, 'Smart Green Building Design and Energy Efficiency', 1, NULL, NULL),
(3, 'AI-Driven Data Analytics and Blockchain Integration for Future Business Decision-Making', 1, NULL, NULL),
(4, 'Parametric Design for Intelligent and Adaptive Interior Environments with Visual Data Integration', 1, NULL, NULL),
(5, 'Sustainable Transportation Systems and Smart City Integration', 1, NULL, NULL),
(6, 'Digital Business and Sustainable Entrepreneurship', 4, NULL, NULL),
(7, 'Sustainable Financial Management', 4, NULL, NULL),
(8, 'Sustainable Investment and Behavioral Finance', 4, NULL, NULL),
(9, 'Human Capital Management and Leadership for Sustainable Growth', 4, NULL, NULL),
(10, 'Sustainable Consumer Behavior and Retail Management', 4, NULL, NULL),
(11, 'Integration of Financial Technology (FinTech) for Sustainable Development Goals (SDG\'s)', 4, NULL, NULL),
(12, 'Risk Management and Corporate Governance for Sustainable Business', 4, NULL, NULL),
(13, 'Sustainable Tourism (Macro Level)', 3, NULL, NULL),
(14, 'Smart Tourism and Technology Integration', 3, NULL, NULL);
INSERT INTO `risettemas` (`id`, `risetfakultas_id`, `jenishibah_id`, `nama`, `keterangan`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 1, 16, 'Smart Urban Planning for Sustainable Cities', 'Exploring the integration of smart technologies (IoT, AI) in urban planning to create energy-efficient, green cities.\r\nDeveloping models for sustainable transport systems, waste management, and renewable energy integration in urban environments.', NULL, NULL, NULL, NULL),
(2, 1, 16, 'Green Building Design and Construction', 'Innovative architectural approaches for energy-efficient and eco-friendly buildings.\r\nUse of sustainable materials and construction practices in the development of buildings with a reduced environmental footprint.\r\nImplementing biophilic design to enhance well-being and create harmony with nature.', NULL, NULL, NULL, NULL),
(3, 1, 16, 'Sustainable Infrastructure Development\r\n', 'Development of resilient infrastructures that withstand climate change impacts and natural disasters. Designing smart infrastructure systems that optimize resource usage, such as water management, renewable energy grids, and sustainable transport networks.', NULL, NULL, NULL, NULL),
(4, 1, 16, 'Data-Driven Project Management for Sustainability\r\n', 'Leveraging information systems for real-time monitoring and analysis of resource consumption, project performance, and environmental impact.\r\nImplementing blockchain technology for transparent and secure tracking of sustainable development projects.', NULL, NULL, NULL, NULL),
(5, 1, 16, 'Circular Economy in Urban Development\r\n', 'Integrating the principles of a circular economy in planning and development, focusing on resource efficiency, waste reduction, and recycling.\r\nUrban regeneration and adaptive reuse of existing buildings and spaces to minimize urban sprawl.', NULL, NULL, NULL, NULL),
(6, 1, 15, 'Sustainable Housing Solutions for Low-Income Communities\r\n', 'Working with local governments and communities to develop affordable, sustainable housing that uses energy-efficient materials and designs to reduce costs and environmental impact.', NULL, NULL, NULL, NULL),
(7, 1, 15, 'Green Public Spaces for Community Well-Being\r\n', 'Engaging with community stakeholders to design and implement eco-friendly public spaces, such as parks, community gardens, and recreational areas, that promote health, well-being, and environmental stewardship.', NULL, NULL, NULL, NULL),
(8, 1, 15, 'Community Education on Renewable Energy Usage\r\n', 'Organizing workshops and training sessions to educate communities on the benefits of renewable energy sources, such as solar and wind, and how to adopt them for household use.', NULL, NULL, NULL, NULL),
(9, 1, 15, 'Disaster-Resilient Infrastructure for Vulnerable Areas\r\n', 'Collaborating with local communities in disaster-prone areas to develop and maintain resilient infrastructure, such as flood management systems and earthquake-resistant buildings.', NULL, NULL, NULL, NULL),
(10, 1, 15, 'Smart Waste Management and Recycling Programs\r\n', 'Creating and implementing community-based smart waste management systems that incorporate technology to track and optimize recycling and waste reduction efforts', NULL, NULL, NULL, NULL),
(11, 2, 16, 'Energy-Efficient Building Design', 'Studying the impact of architectural design on energy efficiency, including passive solar designs and optimized natural lighting.', NULL, NULL, NULL, NULL),
(12, 2, 16, ' Smart Home Technologies for Sustainability', 'Investigating the integration of smart IoT devices (smart thermostats, energy monitors) to reduce energy consumption in homes and buildings.', NULL, NULL, NULL, NULL),
(13, 2, 16, 'Building Performance Monitoring', 'Using IoT sensors and AI to monitor real-time building performance, optimizing energy use, air quality, and thermal comfort.', NULL, NULL, NULL, NULL),
(14, 2, 15, 'Community Green Home Projects', 'Partnering with communities to retrofit homes with smart energy-saving technologies, promoting sustainability at the grassroots level.', NULL, NULL, NULL, NULL),
(15, 2, 15, ' Energy Conservation Awareness Campaigns', 'Collaborating with local governments to educate the public on reducing energy consumption through smart home technologies and eco-friendly practices', NULL, NULL, NULL, NULL),
(16, 2, 15, 'Green Building Workshops for Local Builders', 'Offering training sessions for local builders on green construction practices, including the use of sustainable materials and designs.', NULL, NULL, NULL, NULL),
(17, 3, 16, 'Predictive Data Analytics for Strategic Business Decision-Making', 'This research focuses on developing AI models to analyze large datasets from business operations, predicting future trends, consumer behavior, and market dynamics. The goal is to provide actionable insights for better decision-making.', NULL, NULL, NULL, NULL),
(18, 3, 16, 'Blockchain for Secure and Transparent Business Transactions', 'This study explores the use of blockchain technology to create tamper-proof, transparent ledgers for business transactions. It investigates how blockchain can improve the security and efficiency of financial processes, supply chain management, and contracts', NULL, NULL, NULL, NULL),
(19, 3, 16, 'AI-Enabled Fraud Detection in Decentralized Systems', 'Researching the integration of AI algorithms with blockchain to detect fraudulent activities in decentralized systems. This includes real-time monitoring of transactions to identify anomalies and enhance trust in business ecosystems.', NULL, NULL, NULL, NULL),
(20, 3, 16, 'Integration of Big Data and Blockchain for Data Privacy and Security', 'This research addresses the challenge of securing big data using blockchain, ensuring data integrity and privacy in AI-driven decision-making processes. The study will focus on decentralized data storage and the application of encry', NULL, NULL, NULL, NULL),
(21, 3, 15, 'Workshops on AI and Blockchain for Small and Medium Enterprises (SMEs)', 'Providing training to SMEs on how to implement AI-driven data analytics and blockchain to enhance business decision-making, improve transparency, and optimize operations.', NULL, NULL, NULL, NULL),
(22, 3, 15, 'AI-Driven Decision-Making Tools for Community Financial Management', 'Developing and distributing simple AI-powered tools that help local communities manage their financial data more effectively, providing predictive insights into their budgeting, savings, and investment decisions.', NULL, NULL, NULL, NULL),
(23, 3, 15, 'AI and Blockchain Training for University Students and Entrepreneurs\r\n', 'Offering specialized courses and workshops for students and young entrepreneurs on AI and blockchain applications in business, empowering them with the skills to innovate in their future careers.', NULL, NULL, NULL, NULL),
(24, 4, 16, 'Parametric Interior Design for Adaptive Spaces\r\n', 'Investigating how parametric design tools can be applied to interior design to create adaptive spaces where elements like furniture, lighting, and layouts respond dynamically to environmental conditions and user preferences.', NULL, NULL, NULL, NULL),
(25, 4, 16, ' Visual Communication of Building Performance Data\r\n', 'Exploring how visual design and data visualization techniques can be used to communicate real-time building performance metrics to users, creating an intuitive interface that allows occupants to interact with smart building systems.', NULL, NULL, NULL, NULL),
(26, 4, 16, 'AI-Driven Space Optimization and Smart Interior Layouts\r\n', 'Utilizing AI algorithms to optimize interior layouts based on real-time data from sensors, ensuring that space utilization, lighting, and airflow are continuously optimized for comfort and energy efficiency.', NULL, NULL, NULL, NULL),
(27, 4, 16, ' Human-Centric Parametric Design for Well-Being\r\n', 'Researching the impact of parametric design on user well-being, focusing on how smart technologies and adaptive environments can improve health, comfort, and productivity through personalized interior spaces.', NULL, NULL, NULL, NULL),
(28, 4, 15, ' Smart Interior Design for Sustainable Living\r\n', 'Offering workshops to educate homeowners and local communities on how parametric design and smart building technologies can be implemented in everyday spaces to improve energy efficiency and living comfort.', NULL, NULL, NULL, NULL),
(29, 4, 15, ' Interactive Data Visualization for Building Users\r\n', 'Creating easy-to-understand visual communication materials that help occupants of smart buildings interpret real-time data on energy use and environmental conditions, empowering them to take control of their living or working environments.', NULL, NULL, NULL, NULL),
(30, 4, 15, ' Adaptive Smart Spaces for Local Schools and Community Centers\r\n', 'Collaborating with local institutions to design and implement adaptive smart interior spaces using parametric design principles, improving the energy efficiency and comfort of public spaces such as schools and community centers.', NULL, NULL, NULL, NULL),
(31, 5, 16, ' AI-Powered Traffic Management', 'Researching AI algorithms that optimize traffic flow in urban areas, reducing congestion and emissions while improving transportation efficiency.', NULL, NULL, NULL, NULL),
(32, 5, 16, 'Smart Parking Systems', 'Developing IoT-based smart parking solutions that reduce traffic congestion, improve urban mobility, and decrease carbon emissions from vehicles searching for parking spots.', NULL, NULL, NULL, NULL),
(33, 5, 15, ' Public Education on Sustainable Transportation', 'Engaging communities through educational campaigns that highlight the environmental and health benefits of using public transport, cycling, or electric vehicles.', NULL, NULL, NULL, NULL),
(34, 5, 15, 'Smart Transportation Infrastructure in Local Cities', 'Partnering with local governments to implement smart traffic lights and public transport systems that use real-time data for optimization.', NULL, NULL, NULL, NULL),
