INSERT INTO `roadmaps` (`id`, `jenis_giat`, `judul`, `slug`, `abstrak`, `created_at`, `updated_at`) VALUES
(2, 'pkm', 'Sustainable Communities (Komunitas Berkelanjutan)', 'sustainable-communities-komunitas-berkelanjutan', 'Focuses on creating environmentally friendly and resource-efficient communities by integrating green technologies, renewable energy, and sustainable urban planning. This theme aligns with global efforts to combat climate change and promote ecological balance', '2025-09-10 22:12:41', '2025-09-10 22:12:41'),
(3, 'penelitian', 'Sustainable Urban Development (Pembangunan Perkotaan Berkelanjutan)', 'sustainable-urban-development-pembangunan-perkotaan-berkelanjutan', 'Focuses on addressing the challenges of rapid urbanization in Indonesia, including traffic congestion, waste management, and affordable housing. This theme emphasizes green infrastructure and smart city initiatives to create livable urban environments.', '2025-09-10 23:02:40', '2025-09-10 23:02:40');
